<?php
namespace App\Services\Assessment;
use App\Models\ExamPaper;use App\Models\ExamResult;use App\Models\Learner;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class ExamResultService{public function create(array$d,string$school,?string$user):ExamResult{$paper=ExamPaper::current()->with('examLearningArea.exam')->whereKey($d['paper_id'])->whereHas('examLearningArea.exam',fn($q)=>$q->where('school_id',$school)->where('status','published')->where('is_deleted',false))->first();$learner=Learner::whereKey($d['learner_id'])->where('school_id',$school)->where('active',true)->where('is_deleted',false)->first();if(!$paper||!$learner)throw ValidationException::withMessages(['result'=>'The learner or published exam paper is unavailable outside this school.']);if($d['marks']<0||$d['marks']>$paper->max_marks)throw ValidationException::withMessages(['marks'=>"Marks must be between 0 and {$paper->max_marks}."]);if(ExamResult::current()->where('learner_id',$learner->id)->where('paper_id',$paper->id)->exists())throw ValidationException::withMessages(['paper_id'=>'A result already exists for this learner and paper.']);$area=$paper->examLearningArea;return ExamResult::create(['id'=>(string)Str::uuid(),'exam_id'=>$area->exam_id,'learner_id'=>$learner->id,'learning_area_id'=>$area->learning_area_id,'paper_id'=>$paper->id,'marks'=>$d['marks'],'entered_by'=>$user??$d['entered_by']??null,'is_deleted'=>false,'created_at'=>now()]);}}
